mapper.select:
SELECT STORE_ID, STORE_NAME, CATEGORY, DESCRIPTION, PHONE, ADDRESS, TARGET_CUSTOMER, TARGET_DESCRIPTION,
       TONE_MANNER, TONE_DESCRIPTION, BRAND_COLOR, HERO_IMAGE_URL
  FROM STORE WHERE MEMBER_ID = #{memberId}

SELECT PRODUCT_ID, PRODUCT_NAME, PRICE, DESCRIPTION, IMAGE_URL
  FROM PRODUCT WHERE STORE_ID = #{storeId} AND SALE_STATUS = #{status}
 ORDER BY PRODUCT_ID

mapper.update:
UPDATE PRODUCT SET SALE_STATUS = 'STOPPED', UPDATED_AT = SYSDATE
 WHERE STORE_ID = #{storeId} AND SALE_STATUS = 'ON_SALE'

   AND PRODUCT_ID NOT IN #{id}
